EGEL_DATA.meta({"version":"2026-10-28","built":"2026-10-28T03:06:57.616Z","exam":{"name":"EGEL Plus COMPU (Licenciatura en Ciencias Computacionales)","guide":"Guía para el sustentante, Ceneval, julio de 2022","total":200,"disciplinar":140,"transversal":60,"options":3,"hours":8,"sessions":"2 sesiones de 4 horas el mismo día (9-13 h: disciplinar parte 1; 15-19 h: disciplinar parte 2 + Lenguaje y Comunicación)","pilot":"15% de reactivos piloto que no cuentan","innovation":"hasta 15% de reactivos de innovación: opción múltiple con 2 correctas de 5, respuesta construida numérica/alfanumérica y ordenamiento de elementos","formats":["cuestionamiento directo","completamiento","relación de elementos","multirreactivo (estímulo + varias preguntas)"],"scale":"Índice Ceneval 700-1300 por área: 700-999 Aún no satisfactorio, 1000-1149 Satisfactorio, 1150-1300 Sobresaliente","global":"Modelo conjuntivo: Sobresaliente global = Sobresaliente en Disciplinar + (Sobresaliente o Satisfactorio) en Lenguaje y Comunicación","calculator":"Se permite calculadora científica no programable"},"areas":[{"id":"A1","name":"Algoritmia","short":"Algoritmia","items":40,"def":"Análisis y diseño de algoritmos mediante métodos y técnicas de matemáticas discretas, estructuras de datos y lógica computacional, para la solución de problemas en diversos ámbitos."},{"id":"A2","name":"Desarrollo de software de base","short":"Software de base","items":30,"def":"Desarrollo de software de base por medio de la arquitectura de computadoras, compiladores, sistemas operativos y redes de computadoras, para ofrecer entornos de operación e interacción entre usuarios, dispositivos y aplicaciones."},{"id":"A3","name":"Desarrollo de software de aplicación","short":"Software de aplicación","items":40,"def":"Desarrollo de software de aplicación con el uso de metodologías, normas y estándares de calidad y seguridad informática, lenguajes de programación y bases de datos, para brindar soluciones integrales a problemas específicos en diversos contextos."},{"id":"A4","name":"Soluciones de cómputo inteligente","short":"Cómputo inteligente","items":30,"def":"Principios teóricos y prácticos de inteligencia artificial, tales como representación del conocimiento y métodos de búsqueda, minería de datos y cómputo distribuido, para brindar soluciones inteligentes que apoyen la toma de decisiones en situaciones complejas."},{"id":"LC","name":"Lenguaje y Comunicación","short":"Lenguaje y Comunicación","items":60,"def":"Sección transversal común a todas las profesiones: comprensión lectora (30 reactivos) y redacción indirecta (30 reactivos). No evalúa contenidos memorísticos ni definiciones gramaticales, sino la habilidad de comprender textos y de seleccionar el texto correctamente redactado."}],"subs":[{"code":"1.1","area":"A1","name":"Análisis y diseño de algoritmos","short":"Algoritmos","exam":10,"topics":[{"id":"t01","name":"Notación asintótica","lvl":"S","points":"O, Ω, Θ (y o pequeña); jerarquía 1 < log n < √n < n < n log n < n² < n³ < 2ⁿ < n!; reglas de suma y producto; simplificar expresiones; comparar algoritmos por crecimiento; mejor, peor y caso promedio"},{"id":"t02","name":"Complejidad de algoritmos iterativos","lvl":"S","points":"contar operaciones en ciclos simples, anidados y dependientes (Σi = n(n+1)/2); ciclos con i*=2 o i/=2 → log n; ciclos con raíz; pseudocódigo al estilo Ceneval (Procedimiento/Inicio/Fin, para...hacer, si...entonces); complejidad espacial"},{"id":"t03","name":"Recursividad","lvl":"SS","points":"caso base y caso recursivo; traza de llamadas y pila de recursión; qué imprime/regresa una función recursiva (C, Java, Python, pseudocódigo); recursión de cola; recursión múltiple (Fibonacci, Hanoi); recursión vs iteración; desbordamiento de pila"},{"id":"t04","name":"Recurrencias y teorema maestro","lvl":"SS","points":"plantear la recurrencia de un algoritmo; sustitución y árbol de recursión; teorema maestro T(n)=aT(n/b)+f(n) con sus 3 casos; recurrencias típicas: búsqueda binaria, mergesort, T(n)=2T(n-1)+1 (Hanoi), T(n)=T(n-1)+n, Fibonacci ingenuo"},{"id":"t05","name":"Algoritmos de ordenamiento","lvl":"S","points":"burbuja, selección, inserción, mergesort, quicksort (elección de pivote, partición, peor caso O(n²) con datos ordenados y pivote extremo, promedio O(n log n)), heapsort, counting sort y radix sort; estabilidad, in-place, memoria adicional; estado del arreglo tras k pasadas; cota inferior Ω(n log n) por comparaciones"},{"id":"t06","name":"Algoritmos de búsqueda","lvl":"S","points":"búsqueda secuencial; búsqueda binaria (precondición de orden, traza de índices izquierda/derecha/medio, número máximo de comparaciones ⌊log₂ n⌋+1); búsqueda por interpolación; elegir el método según el escenario"},{"id":"t07","name":"Divide y vencerás","lvl":"SS","points":"dividir, resolver, combinar; mergesort, quicksort, búsqueda binaria, potencia rápida, máximo subarreglo, Karatsuba/Strassen a nivel conceptual; análisis con recurrencias"},{"id":"t08","name":"Algoritmos voraces","lvl":"SS","points":"propiedad de elección voraz y subestructura óptima; cambio de monedas (cuándo falla el voraz), selección de actividades, mochila fraccionaria, códigos de Huffman (construir y longitud de código); Prim, Kruskal y Dijkstra como voraces"},{"id":"t09","name":"Programación dinámica","lvl":"SS","points":"subproblemas superpuestos y subestructura óptima; memoización vs tabulación; Fibonacci, mochila 0/1, subsecuencia común más larga (LCS), distancia de edición, cambio mínimo de monedas, multiplicación encadenada de matrices; llenar celdas de una tabla; diferencia con voraz y con divide y vencerás"},{"id":"t10","name":"Backtracking y ramificación y poda","lvl":"SS","points":"espacio de soluciones como árbol; N-reinas, suma de subconjuntos, generación de permutaciones y combinaciones; criterios de poda; ramificación y poda con cotas; comparación con fuerza bruta"},{"id":"t11","name":"Algoritmos sobre grafos","lvl":"SS","points":"Dijkstra (traza de distancias, no admite pesos negativos), Bellman-Ford, Floyd-Warshall, Prim y Kruskal (peso del árbol de expansión mínima, orden de aristas), orden topológico; complejidades con matriz vs lista de adyacencia y montículo"},{"id":"t12","name":"Corrección e inducción matemática","lvl":"SS","points":"invariantes de ciclo (inicialización, mantenimiento, terminación); prueba por inducción de algoritmos y fórmulas (caso base, hipótesis, paso inductivo); corrección parcial y total; terminación"},{"id":"t13","name":"Clases de complejidad","lvl":"SS","points":"problemas tratables e intratables; P, NP, NP-completo, NP-difícil; reducción polinomial; ejemplos (SAT, agente viajero, mochila, coloreo, ciclo hamiltoniano); qué implica P=NP; diferencia entre intratable e indecidible"},{"id":"t14","name":"Diseño y prueba de escritorio","lvl":"S","points":"algoritmo, pseudocódigo y diagrama de flujo; estructuras secuencial, selectiva y repetitiva; prueba de escritorio (traza de variables) para determinar la salida; identificar el propósito de un algoritmo; errores lógicos comunes (límites de ciclo)"}]},{"code":"1.2","area":"A1","name":"Estructuras de datos","short":"Estructuras de datos","exam":10,"topics":[{"id":"t01","name":"Arreglos y matrices","lvl":"S","points":"acceso por índice O(1); dirección de memoria en orden por renglones y por columnas (base + (i·m + j)·tamaño); matrices dispersas; arreglos dinámicos y crecimiento amortizado; arreglos paralelos"},{"id":"t02","name":"Listas enlazadas","lvl":"S","points":"simple, doble y circular; nodo y referencias; insertar/eliminar al inicio, al final y en medio; complejidades; traza de código con nodos (C con punteros, Java con referencias); nodo centinela; lista vs arreglo"},{"id":"t03","name":"Pilas","lvl":"S","points":"LIFO, push/pop/peek; implementación con arreglo y con lista; traza de una secuencia de operaciones; balanceo de símbolos; conversión infija→postfija y evaluación de postfija; pila de llamadas; deshacer/rehacer"},{"id":"t04","name":"Colas","lvl":"S","points":"FIFO, encolar/desencolar; cola circular (índices frente y final, condición de llena/vacía); bicola (deque); cola de prioridad; traza de operaciones; aplicaciones (BFS, búferes, planificación)"},{"id":"t05","name":"Tablas hash","lvl":"SS","points":"función hash (método de división h(k)=k mod m, multiplicación, plegamiento, hash de cadenas); colisiones; encadenamiento separado vs direccionamiento abierto (sondeo lineal, cuadrático, doble hash) — posición final de claves insertadas; agrupamiento primario; factor de carga α; rehashing; complejidad promedio O(1) y peor caso O(n); eliminación con marcas"},{"id":"t06","name":"Colecciones hash en Java","lvl":"SS","points":"HashSet, LinkedHashSet y TreeSet (orden de iteración: no garantizado, de inserción, natural/Comparator); HashMap, LinkedHashMap, TreeMap y Hashtable (null permitido o no, sincronización); contrato equals/hashCode (objeto sin hashCode sobrescrito → duplicados en HashSet); claves mutables; add() que regresa false; put() que regresa el valor anterior; TreeSet con compareTo inconsistente descarta elementos; qué imprime un programa con estas colecciones"},{"id":"t07","name":"Árboles y recorridos","lvl":"SS","points":"terminología (raíz, hoja, nivel, altura, profundidad, grado); árbol binario lleno, completo y perfecto; máximo de nodos 2^(h+1)−1; recorridos preorden, inorden, postorden y por niveles; reconstruir un árbol a partir de dos recorridos; árboles de expresión; recorridos recursivos (contar nodos, altura)"},{"id":"t08","name":"Árboles binarios de búsqueda","lvl":"SS","points":"propiedad de orden; inserción y búsqueda; eliminación (hoja, un hijo, dos hijos con sucesor/predecesor inorden); árbol resultante de una secuencia de inserciones; inorden da los datos ordenados; complejidad O(h), degenerado O(n)"},{"id":"t09","name":"Árboles balanceados y multicamino","lvl":"SS","points":"AVL (factor de equilibrio, rotaciones simples y dobles tras insertar); rojinegros (propiedades); árboles B y B+ (orden, división de nodos, uso en índices de BD y sistemas de archivos); tries para cadenas"},{"id":"t10","name":"Montículos y colas de prioridad","lvl":"SS","points":"propiedad de montículo (máx/mín); representación en arreglo (hijos 2i+1 y 2i+2, padre ⌊(i−1)/2⌋); inserción con flotación; extracción con hundimiento; construir montículo en O(n); heapsort; PriorityQueue de Java"},{"id":"t11","name":"Grafos: representación y recorridos","lvl":"SS","points":"dirigidos, no dirigidos, ponderados, conexos, completos, bipartitos, DAG; matriz vs lista de adyacencia (espacio y operaciones); grado de entrada y salida; BFS y DFS (orden de visita desde un vértice, uso de cola y pila); componentes conexas; detección de ciclos"},{"id":"t12","name":"TAD y selección de estructuras","lvl":"S","points":"tipo abstracto de datos: interfaz vs implementación; elegir la estructura adecuada para un escenario según operaciones frecuentes; tabla comparativa de complejidades (búsqueda, inserción, eliminación) en arreglo, lista, pila, cola, hash, ABB, montículo"},{"id":"t13","name":"Memoria dinámica","lvl":"SS","points":"pila vs montículo (heap) de memoria; malloc/free, new/delete; recolector de basura; fugas de memoria y apuntadores colgantes; referencias nulas; costo en memoria de cada estructura"}]},{"code":"1.3","area":"A1","name":"Matemáticas discretas","short":"Matemáticas discretas","exam":10,"topics":[{"id":"t01","name":"Sistemas numéricos","lvl":"S","points":"conversiones entre bases 2, 8, 10 y 16 (incluyendo fracciones); aritmética binaria; complemento a 1 y a 2; rango de enteros con signo en n bits; desbordamiento; BCD; nociones de IEEE 754 (signo, exponente con sesgo, mantisa)"},{"id":"t02","name":"Teoría de conjuntos","lvl":"S","points":"unión, intersección, diferencia, complemento, diferencia simétrica; leyes de De Morgan y de conjuntos; conjunto potencia (2ⁿ elementos); producto cartesiano; cardinalidad; inclusión-exclusión con 2 y 3 conjuntos; diagramas de Venn"},{"id":"t03","name":"Relaciones","lvl":"S","points":"propiedades reflexiva, simétrica, antisimétrica y transitiva; relaciones de equivalencia y clases de equivalencia; órdenes parciales y diagramas de Hasse; representación matricial y con dígrafos; composición y cerradura transitiva"},{"id":"t04","name":"Funciones","lvl":"S","points":"dominio, codominio e imagen; inyectiva, sobreyectiva, biyectiva; composición e inversa; piso, techo y módulo; conteo de funciones entre conjuntos finitos"},{"id":"t05","name":"Matrices","lvl":"S","points":"suma y producto (dimensiones compatibles), transpuesta, identidad, determinante 2×2 y 3×3, inversa 2×2; matrices booleanas y producto booleano; matriz de adyacencia y sus potencias (número de caminos de longitud k)"},{"id":"t06","name":"Reglas de conteo y permutaciones","lvl":"S","points":"principio de la suma y del producto; permutaciones n! y P(n,r); permutaciones con repetición (palabras con letras repetidas); arreglos con repetición nʳ (contraseñas, placas); permutaciones circulares; principio del palomar"},{"id":"t07","name":"Combinaciones","lvl":"SS","points":"C(n,r); combinaciones con repetición C(n+r−1,r); distinguir cuándo importa el orden; comités con restricciones (al menos, a lo más, incluir/excluir); triángulo de Pascal; teorema del binomio (coeficiente de un término)"},{"id":"t08","name":"Inducción y sucesiones","lvl":"SS","points":"inducción simple y fuerte; sumatorias Σi, Σi², series geométricas; sucesiones aritméticas y geométricas; definiciones recursivas; relaciones de recurrencia lineales (Fibonacci) y su solución"},{"id":"t09","name":"Teoría de grafos","lvl":"S","points":"lema del apretón de manos (Σ grados = 2|E|); caminos y circuitos eulerianos (condición de grados) y hamiltonianos; árboles (|E| = |V|−1); grafos completos Kₙ con n(n−1)/2 aristas; bipartitos; planaridad y fórmula de Euler V − E + C = 2; isomorfismo; coloración y número cromático"},{"id":"t10","name":"Redes de Petri","lvl":"S","points":"lugares, transiciones, arcos con peso y marcas (tokens); transición habilitada y disparo; marcado resultante tras una secuencia de disparos; alcanzabilidad; bloqueo, vivacidad y acotamiento; modelado de concurrencia, sincronización, exclusión mutua y productor-consumidor"},{"id":"t11","name":"Aritmética modular y teoría de números","lvl":"S","points":"divisibilidad, primos, MCD con algoritmo de Euclides, mcm; congruencias y aritmética mod n; inverso modular; relación con funciones hash y con RSA"},{"id":"t12","name":"Probabilidad discreta","lvl":"S","points":"espacio muestral y eventos; probabilidad clásica con conteo; probabilidad condicional; independencia; teorema de Bayes en problemas sencillos"}]},{"code":"1.4","area":"A1","name":"Lógica computacional","short":"Lógica","exam":10,"topics":[{"id":"t01","name":"Proposiciones y conectivos","lvl":"S","points":"proposición simple y compuesta; ¬, ∧, ∨, →, ↔, ⊕; jerarquía de operadores; traducir del lenguaje natural (si...entonces, solo si, es necesario, es suficiente, a menos que, ni...ni); valor de verdad de una expresión dada"},{"id":"t02","name":"Tablas de verdad","lvl":"S","points":"2ⁿ renglones; construir y leer tablas; tautología, contradicción y contingencia; satisfacibilidad; equivalencia mediante tablas; renglón que hace falsa una implicación"},{"id":"t03","name":"Equivalencias y formas normales","lvl":"S","points":"leyes de De Morgan, distributivas, absorción, doble negación; p → q ≡ ¬p ∨ q; contrapositiva (equivalente) vs recíproca e inversa (no equivalentes); simplificación de expresiones; forma normal conjuntiva y disyuntiva"},{"id":"t04","name":"Reglas de inferencia","lvl":"SS","points":"modus ponens, modus tollens, silogismo hipotético y disyuntivo, simplificación, adición, conjunción, dilema constructivo, resolución; validez de argumentos; derivar una conclusión de premisas; falacias de afirmar el consecuente y negar el antecedente"},{"id":"t05","name":"Lógica de predicados","lvl":"SS","points":"predicados y cuantificadores ∀ y ∃; traducir enunciados (todos, algunos, ninguno, no todos); negación de cuantificadores; variables libres y ligadas; orden de cuantificadores (∀x∃y vs ∃y∀x); valor de verdad en un dominio finito; reglas de inferencia con cuantificadores (instanciación y generalización)"},{"id":"t06","name":"Representación del conocimiento con predicados","lvl":"SS","points":"formalizar una base de conocimiento; forma clausal y cláusulas de Horn; unificación (unificador más general); resolución en primer orden; Prolog: hechos, reglas, consultas, unificación y backtracking; qué responde una consulta"},{"id":"t07","name":"Álgebra de Boole","lvl":"S","points":"postulados y teoremas (idempotencia, absorción, De Morgan, consenso); dualidad; simplificación algebraica; minitérminos y maxitérminos; suma de productos y producto de sumas; notación Σm y ΠM; función a partir de su tabla"},{"id":"t08","name":"Mapas de Karnaugh","lvl":"S","points":"mapas de 2, 3 y 4 variables en código Gray; agrupaciones de 1, 2, 4, 8 celdas; condiciones no importa (X); expresión mínima en SOP y POS"},{"id":"t09","name":"Compuertas y circuitos combinacionales","lvl":"S","points":"AND, OR, NOT, NAND, NOR, XOR, XNOR; NAND y NOR como compuertas universales; analizar un circuito (expresión y tabla); diseñar a partir de una especificación; medio sumador y sumador completo; multiplexor, demultiplexor, decodificador, codificador, comparador"},{"id":"t10","name":"Circuitos secuenciales","lvl":"SS","points":"diferencia combinacional vs secuencial; latch y flip-flops SR, D, JK y T (tablas características); registros y contadores; máquinas de estado de Mealy y Moore"}]},{"code":"2.1","area":"A2","name":"Arquitectura de computadoras y sistemas operativos","short":"Arquitectura y SO","exam":10,"topics":[{"id":"t01","name":"Arquitectura de Von Neumann","lvl":"S","points":"CPU (ALU, unidad de control, registros PC, IR, MAR, MDR, acumulador, banderas), memoria principal, E/S y buses (datos, direcciones, control; ancho del bus de direcciones → memoria direccionable); concepto de programa almacenado; cuello de botella de Von Neumann; Von Neumann vs Harvard"},{"id":"t02","name":"Ciclo de instrucción y procesamiento secuencial","lvl":"S","points":"etapas búsqueda-decodificación-ejecución (y escritura); uso de PC, IR, MAR y MDR en cada etapa; modos de direccionamiento (inmediato, directo, indirecto, registro, indexado, relativo); formato de instrucción; CISC vs RISC; interrupciones y su atención"},{"id":"t03","name":"Jerarquía de memoria y caché","lvl":"S","points":"registros, caché L1/L2/L3, RAM, almacenamiento secundario (costo, velocidad, capacidad); localidad temporal y espacial; correspondencia directa, totalmente asociativa y asociativa por conjuntos (campos etiqueta/índice/desplazamiento); tasa de aciertos y tiempo promedio de acceso; políticas de reemplazo y de escritura"},{"id":"t04","name":"Procesamiento paralelo","lvl":"SS","points":"segmentación (pipeline): etapas, ciclos para k instrucciones en m etapas, riesgos estructurales, de datos y de control; superescalar; taxonomía de Flynn (SISD, SIMD, MISD, MIMD); multinúcleo y multiprocesador (memoria compartida vs distribuida); ley de Amdahl (cálculo de aceleración)"},{"id":"t05","name":"Tipos y estructura de sistemas operativos","lvl":"S","points":"funciones del SO; por lotes, multiprogramados, tiempo compartido, tiempo real (duro/suave), distribuidos, de red, embebidos, móviles; monousuario/multiusuario, monotarea/multitarea; núcleo monolítico, microkernel, capas, híbrido; modo usuario y modo kernel; llamadas al sistema"},{"id":"t06","name":"Gestión de procesos e hilos","lvl":"S","points":"proceso vs programa; PCB; estados (nuevo, listo, ejecución, bloqueado, terminado) y transiciones válidas; cambio de contexto; hilos de usuario y de kernel; fork() en C (cuántas veces imprime), exec y wait; procesos huérfanos y zombis"},{"id":"t07","name":"Planificación de la CPU","lvl":"S","points":"FCFS, SJF, SRTF, prioridades (apropiativa y no apropiativa), Round Robin con quantum, colas multinivel; diagrama de Gantt; tiempos de espera, retorno y respuesta promedio (cálculo); efecto convoy; inanición y envejecimiento"},{"id":"t08","name":"Concurrencia, sincronización e interbloqueo","lvl":"SS","points":"condición de carrera y sección crítica; exclusión mutua, progreso y espera acotada; semáforos (wait/signal, valor inicial), mutex, monitores; productor-consumidor, lectores-escritores, filósofos; condiciones de Coffman; prevención, evasión (algoritmo del banquero, estado seguro) y detección/recuperación"},{"id":"t09","name":"Administración de memoria","lvl":"S","points":"particiones fijas y variables; fragmentación interna y externa; primer, mejor y peor ajuste; paginación (número de página y desplazamiento, traducción de direcciones, tabla de páginas, TLB); segmentación; memoria virtual y fallos de página; reemplazo FIFO, LRU y óptimo (contar fallos), anomalía de Belady; hiperpaginación"},{"id":"t10","name":"Sistemas de archivos y E/S","lvl":"SS","points":"archivos, directorios y rutas; asignación contigua, enlazada (FAT) e indexada (i-nodos); FAT32, NTFS, ext4, journaling; permisos rwx y chmod octal; planificación de disco FCFS, SSTF, SCAN, C-SCAN (desplazamiento total); RAID 0, 1, 5; E/S programada, por interrupciones y DMA"},{"id":"t11","name":"Interfaces humano-computadora","lvl":"SS","points":"principios de Norman (affordance, retroalimentación, mapeo, restricciones, consistencia); heurísticas de Nielsen; ley de Fitts y ley de Hick; modelo GOMS/KLM; estilos de interacción (CLI, GUI, táctil, por voz y conversacional, gestual); evaluación heurística y pruebas con usuarios; accesibilidad"}]},{"code":"2.2","area":"A2","name":"Compiladores","short":"Compiladores","exam":10,"topics":[{"id":"t01","name":"Fases de un compilador","lvl":"S","points":"análisis léxico, sintáctico y semántico; generación de código intermedio; optimización; generación de código objeto; tabla de símbolos y manejo de errores; front-end y back-end; en qué fase se detecta cada tipo de error; compilador vs intérprete vs JIT; preprocesador, ensamblador, enlazador y cargador"},{"id":"t02","name":"Análisis léxico","lvl":"S","points":"token, lexema y patrón; contar y clasificar tokens de una línea de código; expresiones regulares para identificadores, números y comentarios; regla de la coincidencia más larga; generadores (lex/flex); errores léxicos"},{"id":"t03","name":"Expresiones regulares","lvl":"S","points":"unión, concatenación, cerradura de Kleene (*), +, ?; lenguaje que denota una ER; construir la ER de un lenguaje; cadenas que pertenecen o no; equivalencia de ER; lenguajes regulares y sus propiedades de cerradura"},{"id":"t04","name":"Autómatas finitos","lvl":"SS","points":"AFD, AFN y AFN-ε; función de transición y traza de aceptación; lenguaje que acepta un autómata; construir un AFD para un lenguaje; conversión AFN→AFD por subconjuntos; ER→AFN (Thompson); minimización de AFD; equivalencia entre autómatas; lema de bombeo y lenguajes no regulares (aⁿbⁿ)"},{"id":"t05","name":"Gramáticas libres de contexto","lvl":"SS","points":"G = (V, T, P, S); derivaciones por la izquierda y derecha; árboles de derivación; ambigüedad; diseñar una gramática para un lenguaje dado; jerarquía de Chomsky (tipos 0 a 3) y su autómata asociado; BNF/EBNF; eliminación de recursividad izquierda y factorización"},{"id":"t06","name":"Autómatas de pila","lvl":"S","points":"definición; aceptación por estado final o por pila vacía; AP para aⁿbⁿ, paréntesis balanceados y palíndromos; configuración y traza; equivalencia con gramáticas libres de contexto; deterministas vs no deterministas"},{"id":"t07","name":"Máquinas de Turing y computabilidad","lvl":"S","points":"definición formal δ(q, a) = (p, b, L/R); traza sobre la cinta (contenido final, estado final, si acepta o se detiene); diseñar MT sencillas (complemento binario, incremento, suma unaria, aⁿbⁿ); variantes equivalentes (multicinta, no determinista); MT universal; tesis de Church-Turing; problema de la parada; decidible, semidecidible e indecidible; Turing-completitud (por ejemplo, el Juego de la vida)"},{"id":"t08","name":"Análisis sintáctico","lvl":"SS","points":"descendente: recursivo, LL(1), conjuntos PRIMERO y SIGUIENTE, tabla LL(1); ascendente: desplazamiento-reducción, LR(0), SLR, LALR, LR(1), conflictos desplazar/reducir y reducir/reducir; yacc/bison; recuperación de errores"},{"id":"t09","name":"Análisis semántico","lvl":"S","points":"comprobación de tipos y coerciones; ámbitos y tabla de símbolos; atributos sintetizados y heredados; definiciones dirigidas por la sintaxis; errores semánticos típicos (tipos incompatibles, variable no declarada, número de argumentos)"},{"id":"t10","name":"Código intermedio y optimización","lvl":"S","points":"código de tres direcciones para una expresión o sentencia; cuádruplas y tripletas; árbol sintáctico abstracto, DAG y notación postfija; optimizaciones (plegado y propagación de constantes, subexpresiones comunes, código muerto, invariantes de ciclo, mirilla); asignación de registros; registros de activación"}]},{"code":"2.3","area":"A2","name":"Redes de computadoras","short":"Redes","exam":10,"topics":[{"id":"t01","name":"Conceptos, topologías y desempeño","lvl":"S","points":"PAN, LAN, MAN, WAN; topologías bus, estrella, anillo, malla, árbol (ventajas y fallas); conmutación de circuitos vs de paquetes; ancho de banda, throughput y latencia; retardos de transmisión (L/R), propagación (d/s), procesamiento y cola (cálculo); cliente-servidor vs P2P"},{"id":"t02","name":"Modelo OSI","lvl":"S","points":"7 capas y sus funciones; PDU de cada capa (bits, trama, paquete, segmento, datos); encapsulamiento y desencapsulamiento; ubicar protocolos, servicios y dispositivos en su capa; servicios orientados y no orientados a conexión"},{"id":"t03","name":"Modelo TCP/IP","lvl":"S","points":"capas de TCP/IP y correspondencia con OSI; protocolos por capa; diferencias y ventajas de cada modelo; arquitectura de Internet"},{"id":"t04","name":"Capa física y medios de transmisión","lvl":"S","points":"UTP/STP y categorías, T568A/T568B, cable directo vs cruzado; coaxial; fibra monomodo y multimodo; inalámbrico; codificación NRZ y Manchester; modulación ASK, FSK, PSK, QAM; teoremas de Nyquist y Shannon (cálculo de capacidad); multiplexación FDM, TDM, WDM"},{"id":"t05","name":"Capa de enlace y Ethernet","lvl":"SS","points":"trama y dirección MAC (48 bits, OUI); detección de errores (paridad, CRC, checksum) y corrección (Hamming); CSMA/CD y CSMA/CA; Ethernet 802.3 y Wi-Fi 802.11; switch: tabla MAC y autoaprendizaje; dominios de colisión y de difusión; VLAN y enlaces troncales 802.1Q; STP; ARP; PPP"},{"id":"t06","name":"Dispositivos de interconexión","lvl":"S","points":"repetidor, hub, puente, switch, router, gateway, punto de acceso, módem, firewall: capa OSI en que operan y qué dirección usan; cuántos dominios de colisión y de difusión resultan en una topología"},{"id":"t07","name":"Direccionamiento IPv4 y subneteo","lvl":"SS","points":"clases A-E y rangos; direcciones privadas RFC 1918, loopback, APIPA; máscara y notación CIDR; dirección de red, broadcast, rango y número de hosts (2ⁿ − 2); subneteo de longitud fija; VLSM; sumarización de rutas; NAT y PAT"},{"id":"t08","name":"IPv6, ICMP y DHCP","lvl":"S","points":"IPv6: 128 bits, notación hexadecimal y abreviación (::), unicast, multicast, anycast, link-local fe80::/10, sin broadcast; campos del encabezado IPv4 (TTL, fragmentación, protocolo); ICMP (ping, traceroute); DHCP (proceso DORA); mecanismos de transición IPv4/IPv6"},{"id":"t09","name":"Enrutamiento","lvl":"SS","points":"tabla de enrutamiento y coincidencia del prefijo más largo; rutas estáticas, ruta por defecto y dinámicas; vector distancia (RIP, conteo al infinito, horizonte dividido) vs estado de enlace (OSPF con Dijkstra); IGP vs EGP, sistemas autónomos y BGP; métrica y distancia administrativa"},{"id":"t10","name":"Capa de transporte: TCP y UDP","lvl":"SS","points":"puertos y sockets (20/21 FTP, 22 SSH, 23 Telnet, 25 SMTP, 53 DNS, 67/68 DHCP, 80 HTTP, 110 POP3, 143 IMAP, 443 HTTPS); TCP vs UDP; saludo de tres vías y cierre; números de secuencia y de acuse (cálculo); ventana deslizante y control de flujo; control de congestión (arranque lento, AIMD, umbral); Go-Back-N vs repetición selectiva"},{"id":"t11","name":"Capa de aplicación","lvl":"S","points":"HTTP (métodos, códigos de estado, conexiones persistentes, cookies, HTTP/2 y HTTP/3); DNS (jerarquía, consulta recursiva vs iterativa, registros A, AAAA, MX, CNAME, NS, PTR); SMTP, POP3, IMAP; FTP, SSH, Telnet, SNMP; proxies, cachés web y CDN"},{"id":"t12","name":"Seguridad en redes","lvl":"SS","points":"firewalls (filtrado de paquetes, con estado, proxy de aplicación), DMZ y ACL; IDS vs IPS; VPN e IPsec (AH, ESP, modo túnel y transporte); TLS/SSL y certificados; WPA2/WPA3 y 802.1X; ataques DoS/DDoS, SYN flood, spoofing, sniffing, MITM y envenenamiento ARP"},{"id":"t13","name":"Calidad de servicio (QoS)","lvl":"SS","points":"parámetros: ancho de banda, retardo, jitter y pérdida; requisitos de voz, video y datos; IntServ/RSVP vs DiffServ/DSCP; clasificación y marcado; disciplinas de colas (FIFO, prioridad, WFQ); conformación y vigilancia de tráfico (cubeta con goteo, cubeta de fichas); MPLS"}]},{"code":"3.1","area":"A3","name":"Ingeniería de software","short":"Ing. de software","exam":10,"topics":[{"id":"t01","name":"Ciclo de vida y modelos de proceso","lvl":"S","points":"fases (requerimientos, análisis, diseño, construcción, pruebas, implantación, mantenimiento); cascada, incremental, iterativo, espiral (manejo de riesgos), prototipos, modelo en V, RUP (inicio, elaboración, construcción, transición); DevOps e integración/entrega continua; elegir el modelo adecuado para un escenario; fase en que se insertó un error"},{"id":"t02","name":"Metodologías ágiles","lvl":"S","points":"manifiesto ágil (valores y principios); Scrum: roles, eventos (sprint, planeación, scrum diario, revisión, retrospectiva) y artefactos (product backlog, sprint backlog, incremento); XP (programación en pareja, TDD, integración continua, refactorización); Kanban y límites WIP; historias de usuario (INVEST), puntos de historia y velocidad"},{"id":"t03","name":"Ingeniería de requerimientos","lvl":"S","points":"requerimientos funcionales vs no funcionales; técnicas de obtención (entrevista, cuestionario, observación, JAD, lluvia de ideas, prototipos); especificación (IEEE 830 / ISO 29148); validación y trazabilidad; casos de uso para mostrar funcionalidad e interacción de usuarios; gestión de cambios"},{"id":"t04","name":"UML estructural","lvl":"SS","points":"diagrama de clases: atributos, métodos, visibilidad (+ − # ~), multiplicidad, asociación, agregación, composición, generalización, realización, dependencia; traducir diagrama ↔ código; diagramas de objetos, componentes, despliegue y paquetes"},{"id":"t05","name":"UML de comportamiento","lvl":"SS","points":"casos de uso (actores, include vs extend, generalización); secuencia (líneas de vida, mensajes síncronos y asíncronos, fragmentos alt/opt/loop); actividades (decisiones, fork/join, carriles); máquina de estados (eventos, guardas, acciones); comunicación; elegir el diagrama adecuado"},{"id":"t06","name":"Diseño, arquitectura y patrones","lvl":"SS","points":"cohesión alta y acoplamiento bajo; principios SOLID, DRY, KISS; arquitecturas en capas, cliente-servidor, MVC, microservicios, SOA, basada en eventos, tuberías y filtros; patrones Singleton, Factory Method, Abstract Factory, Observer, Strategy, Adapter, Decorator, Facade, Composite, MVC: identificar el patrón en un escenario o código"},{"id":"t07","name":"Pruebas de software","lvl":"S","points":"niveles: unitarias, integración, sistema, aceptación; caja negra (particiones de equivalencia, valores límite) y caja blanca (cobertura de sentencias y ramas, complejidad ciclomática V(G) = E − N + 2); regresión, carga y estrés; alfa y beta; verificación vs validación; TDD"},{"id":"t08","name":"Gestión de proyectos de software","lvl":"S","points":"planeación y alcance; estimación (LOC, puntos de función, COCOMO, juicio experto, Planning Poker, PERT (O + 4M + P)/6); calendarización con Gantt; ruta crítica y holguras (CPM); gestión de riesgos; gestión de la configuración y control de versiones; valor ganado (PV, EV, AC, CPI, SPI)"},{"id":"t09","name":"Calidad y estándares","lvl":"S","points":"ISO/IEC 25010 (características de calidad del producto); ISO 9001; CMMI (5 niveles de madurez); MoProSoft (NMX-I-059) e ISO/IEC 29110; ISO/IEC 12207; aseguramiento de la calidad, revisiones e inspecciones; tipos de mantenimiento (correctivo, adaptativo, perfectivo, preventivo); refactorización y deuda técnica"},{"id":"t10","name":"Usabilidad y experiencia de usuario","lvl":"SS","points":"usabilidad según ISO 9241-11 (eficacia, eficiencia, satisfacción); heurísticas de Nielsen; diseño centrado en el usuario; pruebas de usabilidad (pensamiento en voz alta, tasa de éxito, tiempo en tarea, cuestionario SUS); accesibilidad WCAG (perceptible, operable, comprensible, robusto); diseño web responsivo y arquitectura de información"}]},{"code":"3.2","area":"A3","name":"Lenguajes de programación","short":"Lenguajes","exam":10,"topics":[{"id":"t01","name":"Paradigmas de programación","lvl":"S","points":"imperativo/estructurado, orientado a objetos, funcional, lógico, declarativo vs imperativo, orientado a eventos, concurrente; lenguajes representativos; elegir el paradigma para un problema; programación estructurada (secuencia, selección, iteración)"},{"id":"t02","name":"Características de los lenguajes","lvl":"S","points":"compilado, interpretado e híbrido (bytecode, JVM, JIT); tipado estático vs dinámico, fuerte vs débil, inferencia de tipos; alcance léxico vs dinámico; tiempo de ligadura; gestión manual de memoria vs recolector de basura; paso de parámetros por valor y por referencia (Java pasa copias de referencias); evaluación en cortocircuito y perezosa; tipos nativos (matrices nativas en MATLAB/Fortran)"},{"id":"t03","name":"POO: fundamentos","lvl":"S","points":"clase y objeto; encapsulamiento y modificadores (public, private, protected, por omisión); constructores y sobrecarga; this; miembros static; abstracción; clase abstracta vs interfaz; composición vs herencia; identidad, estado y comportamiento"},{"id":"t04","name":"Herencia y polimorfismo","lvl":"SS","points":"sobrescritura vs sobrecarga; ligadura dinámica; super; orden de ejecución de constructores e inicializadores (qué imprime); upcasting, downcasting y ClassCastException; métodos static se ocultan, no se sobrescriben; los atributos no son polimórficos; final; herencia múltiple (diamante en C++, interfaces y métodos default en Java); métodos virtual en C++ (qué imprime con y sin virtual)"},{"id":"t05","name":"Java esencial","lvl":"SS","points":"String inmutable; == vs equals; pool de cadenas; caché de Integer (−128 a 127) y autoboxing; división entera, %, conversiones y desbordamiento de int; ++ prefijo/postfijo; cortocircuito; switch sin break; arreglos (valores por omisión, referencias compartidas); excepciones: checked vs unchecked, orden de catch, finally siempre se ejecuta, return dentro de finally; StringBuilder"},{"id":"t06","name":"Colecciones e iteradores en Java","lvl":"SS","points":"ArrayList vs LinkedList (complejidades); List.remove(int) vs remove(Object); Iterator y ConcurrentModificationException; Collections.sort con Comparator; genéricos y borrado de tipos; Map.put/getOrDefault/merge; ArrayDeque como pila y cola; PriorityQueue (orden de poll vs toString); Stack"},{"id":"t07","name":"C y C++","lvl":"SS","points":"apuntadores y aritmética de apuntadores; arreglos y apuntadores; paso por referencia (punteros en C, & en C++); cadenas terminadas en '\\0', strlen vs sizeof; struct; malloc/free y new/delete; ++ en expresiones; char y ASCII; printf; variables static; referencias, sobrecarga de operadores y plantillas en C++ (qué imprime)"},{"id":"t08","name":"Programación funcional","lvl":"SS","points":"funciones puras, inmutabilidad y transparencia referencial; funciones de orden superior (map, filter, reduce/fold); lambdas y closures; currificación y composición; recursión en lugar de ciclos; evaluación perezosa; ejemplos en Haskell, Lisp/Scheme, Python, JavaScript y streams de Java (qué produce una cadena map-filter-reduce)"},{"id":"t09","name":"Programación lógica","lvl":"S","points":"Prolog como paradigma declarativo: hechos, reglas y consultas; unificación; backtracking y orden de soluciones; corte (!); listas en Prolog; qué responde una consulta"},{"id":"t10","name":"Python y JavaScript","lvl":"SS","points":"Python: listas mutables y alias, rebanadas, comprensiones, diccionarios y conjuntos, argumentos por omisión mutables, / vs //, range, enumerate/zip, tuplas inmutables, global; JavaScript: == vs ===, coerción, var/let/const, hoisting, closures en ciclos, this, typeof null, arreglos y métodos, promesas y async/await básico"},{"id":"t11","name":"Desarrollo web y móvil","lvl":"S","points":"HTML5 semántico y formularios; CSS3 (selectores, especificidad, modelo de caja, flexbox, grid, media queries); DOM y eventos; PHP (variables $, $_GET, $_POST, $_SESSION, PDO y sentencias preparadas); AJAX/fetch, JSON y REST (métodos HTTP y su semántica); Android (actividades y ciclo de vida onCreate/onStart/onResume/onPause/onStop/onDestroy, intents, manifiesto); apps nativas, híbridas y PWA; formatos multimedia y compresión"}]},{"code":"3.3","area":"A3","name":"Bases de datos","short":"Bases de datos","exam":10,"topics":[{"id":"t01","name":"SMBD y arquitectura","lvl":"S","points":"funciones del SMBD (diccionario de datos, administración del almacenamiento, transformación y presentación, seguridad, control de acceso multiusuario, respaldo y recuperación, integridad, lenguajes de acceso e interfaces); arquitectura ANSI/SPARC de tres niveles; independencia lógica y física; modelos de datos (jerárquico, red, relacional, orientado a objetos, NoSQL); usuarios y DBA"},{"id":"t02","name":"Modelo entidad-relación","lvl":"S","points":"entidades fuertes y débiles; atributos simples, compuestos, multivaluados, derivados y clave; relaciones, grado, cardinalidad (1:1, 1:N, N:M) y participación; notación de Chen y pata de gallo; generalización/especialización; de un enunciado al diagrama; transformación E-R → tablas (llaves foráneas, tabla intermedia N:M, atributos multivaluados)"},{"id":"t03","name":"Modelo relacional y álgebra relacional","lvl":"S","points":"relación, tupla, atributo, dominio, grado y cardinalidad; superllave, llave candidata, primaria, alterna y foránea; integridad de entidad y referencial (CASCADE, SET NULL, RESTRICT); selección σ, proyección π, unión, diferencia, producto cartesiano, reunión ⋈ y división; resultado de una expresión"},{"id":"t04","name":"Normalización","lvl":"SS","points":"dependencias funcionales (completas, parciales, transitivas) y cierre de atributos; 1FN, 2FN, 3FN, FNBC y 4FN; anomalías de inserción, actualización y eliminación; identificar la forma normal de una tabla y descomponerla; desnormalización"},{"id":"t05","name":"SQL: DDL, DML, DCL y TCL","lvl":"S","points":"CREATE, ALTER, DROP; restricciones PRIMARY KEY, FOREIGN KEY, UNIQUE, CHECK, NOT NULL, DEFAULT; INSERT, UPDATE, DELETE; DELETE vs TRUNCATE vs DROP; GRANT y REVOKE; COMMIT, ROLLBACK, SAVEPOINT"},{"id":"t06","name":"Consultas SQL","lvl":"SS","points":"SELECT, WHERE, ORDER BY, DISTINCT; funciones de agregación y NULL (COUNT(*) vs COUNT(col)); GROUP BY y HAVING; INNER, LEFT, RIGHT, FULL y CROSS JOIN y número de filas resultante; subconsultas con IN, EXISTS y correlacionadas; UNION vs UNION ALL; LIKE; comparaciones con NULL; vistas; resultado exacto de una consulta sobre tablas dadas"},{"id":"t07","name":"Programación de bases de datos","lvl":"SS","points":"procedimientos almacenados y funciones (parámetros IN/OUT); disparadores BEFORE/AFTER, INSERT/UPDATE/DELETE, FOR EACH ROW, NEW y OLD (efecto de un trigger); cursores; vistas materializadas; índices (árbol B+, hash, agrupados y no agrupados, cuándo convienen); PL/SQL, T-SQL y PL/pgSQL"},{"id":"t08","name":"Transacciones y concurrencia","lvl":"SS","points":"propiedades ACID y estados de una transacción; lectura sucia, lectura no repetible, fantasmas y actualización perdida; niveles de aislamiento SQL; planificaciones serializables por conflicto y grafo de precedencia; bloqueos compartidos y exclusivos, 2PL y 2PL estricto; interbloqueo (wait-die, wound-wait); marcas de tiempo y MVCC; bitácora, WAL, puntos de control, UNDO/REDO"},{"id":"t09","name":"Bases de datos distribuidas","lvl":"SS","points":"BD centralizada vs distribuida; homogéneas, heterogéneas y federadas; fragmentación horizontal, vertical y mixta; replicación; transparencias de ubicación, fragmentación y replicación; procesamiento de consultas distribuidas; commit de dos fases (coordinador, votación, decisión); control de concurrencia distribuido; teorema CAP y consistencia eventual"},{"id":"t10","name":"Data warehouse y OLAP","lvl":"S","points":"OLTP vs OLAP; data warehouse (orientado a temas, integrado, no volátil, variante en el tiempo) vs BD operacional; data mart; ETL; esquemas estrella, copo de nieve y constelación (hechos y dimensiones); operaciones roll-up, drill-down, slice, dice, pivot; MOLAP, ROLAP, HOLAP; enfoques de Inmon y Kimball"},{"id":"t11","name":"NoSQL","lvl":"S","points":"clave-valor, documentales (MongoDB), columnares (Cassandra, HBase) y de grafos (Neo4j); BASE vs ACID; esquema flexible; particionamiento (sharding); cuándo conviene NoSQL vs relacional"}]},{"code":"3.4","area":"A3","name":"Seguridad informática","short":"Seguridad","exam":10,"topics":[{"id":"t01","name":"Fundamentos de seguridad","lvl":"S","points":"confidencialidad, integridad y disponibilidad; autenticidad, no repudio y trazabilidad; AAA; activo, amenaza, vulnerabilidad, riesgo e impacto; ataques pasivos y activos (interrupción, intercepción, modificación, fabricación); seguridad física y lógica; defensa en profundidad"},{"id":"t02","name":"Criptografía simétrica","lvl":"SS","points":"misma clave para cifrar y descifrar; DES, 3DES, AES (bloque de 128 bits, claves de 128/192/256), Blowfish, Twofish; cifrado por bloques vs de flujo (RC4, ChaCha20); modos ECB, CBC, CTR, GCM (ECB revela patrones); problema de distribución de claves; n(n−1)/2 claves para n usuarios; cifrados clásicos César, Vigenère y transposición"},{"id":"t03","name":"Criptografía asimétrica","lvl":"SS","points":"par de claves pública/privada; cifrar con la pública del destinatario, firmar con la privada del emisor; RSA (p, q, n, φ(n), e, d con números pequeños); Diffie-Hellman (cálculo pequeño, vulnerable a MITM sin autenticación); ElGamal y curvas elípticas; cifrado híbrido; 2n claves para n usuarios"},{"id":"t04","name":"Hash, firmas y certificados","lvl":"SS","points":"propiedades de las funciones hash (una vía, resistencia a colisiones, efecto avalancha); MD5 y SHA-1 (obsoletos), SHA-2 y SHA-3; HMAC; firma digital (hash + clave privada) y su verificación; certificados X.509, PKI, autoridades certificadoras, cadena de confianza y revocación (CRL, OCSP); almacenamiento de contraseñas con sal y funciones lentas (bcrypt, scrypt, Argon2, PBKDF2)"},{"id":"t05","name":"Autenticación y control de acceso","lvl":"SS","points":"factores (algo que sabes, que tienes, que eres) y MFA; OTP y TOTP; biometría (FAR y FRR); Kerberos (KDC, TGT, tickets); OAuth 2.0, OpenID Connect, SSO y JWT; modelos DAC, MAC, RBAC y ABAC; mínimo privilegio y separación de funciones"},{"id":"t06","name":"Malware y ataques","lvl":"S","points":"virus, gusano, troyano, ransomware, spyware, adware, rootkit, keylogger, botnet, puerta trasera, bomba lógica; ingeniería social (phishing, spear phishing, pretexting, baiting); fuerza bruta, diccionario y tablas arcoíris; DoS/DDoS; MITM; día cero; APT"},{"id":"t07","name":"Desarrollo seguro de aplicaciones","lvl":"SS","points":"OWASP Top 10 (inyección, XSS almacenado/reflejado/DOM, CSRF, control de acceso roto, fallas criptográficas, configuración insegura, componentes vulnerables, SSRF); inyección SQL y su prevención con sentencias preparadas; validación de entradas y codificación de salidas; desbordamiento de búfer; manejo seguro de sesiones; SDL/DevSecOps; SAST, DAST y pruebas de penetración (caja negra, gris y blanca)"},{"id":"t08","name":"Mecanismos locales y remotos","lvl":"SS","points":"locales: cuentas y contraseñas del SO, permisos, cifrado de disco, antivirus, firewall de host, arranque seguro, bitácoras, actualizaciones y respaldos; remotos: VPN, SSH, TLS/HTTPS, firewall perimetral, IDS/IPS, proxy, DMZ, RADIUS/TACACS+, segmentación de red; elegir el mecanismo para un escenario"},{"id":"t09","name":"Gestión de la seguridad y continuidad","lvl":"S","points":"análisis de riesgos (probabilidad × impacto) y tratamiento; políticas de seguridad; ISO/IEC 27001 y 27002 (SGSI, ciclo PDCA); plan de continuidad (BCP) y de recuperación ante desastres (DRP); RPO y RTO; respaldo completo, incremental y diferencial (qué se necesita para restaurar); auditoría informática; protección de datos personales (LFPDPPP en México)"}]},{"code":"4.1","area":"A4","name":"Inteligencia artificial","short":"IA","exam":10,"topics":[{"id":"t01","name":"Fundamentos de IA","lvl":"S","points":"enfoques de Russell y Norvig (pensar/actuar como humano o racionalmente); prueba de Turing; IA débil vs fuerte; ramas (sistemas expertos, aprendizaje automático, PLN, visión, robótica, planificación); IA simbólica vs conexionista"},{"id":"t02","name":"Agentes inteligentes","lvl":"S","points":"agente, percepción, acción y función del agente; racionalidad y medida de desempeño; descripción REAS/PEAS de un escenario; propiedades del entorno (observable, determinista/estocástico, episódico/secuencial, estático/dinámico, discreto/continuo, uno o varios agentes); agentes reflejo simple, basados en modelos, en objetivos, en utilidad y que aprenden; sistemas multiagente"},{"id":"t03","name":"Búsqueda no informada","lvl":"SS","points":"formulación de problemas (estado inicial, acciones, modelo de transición, prueba de objetivo, costo); espacio de estados; BFS, DFS, costo uniforme, profundidad limitada, profundidad iterativa y bidireccional; completitud, optimalidad y complejidad O(b^d); orden de expansión de nodos en un grafo dado"},{"id":"t04","name":"Búsqueda informada","lvl":"SS","points":"función heurística; heurística admisible y consistente; voraz primero el mejor; A* con f(n) = g(n) + h(n) (traza y camino resultante); optimalidad de A*; IDA*; heurísticas para el 8-puzzle (fichas mal colocadas, distancia Manhattan) y dominancia"},{"id":"t05","name":"Optimización y búsqueda local","lvl":"SS","points":"características de los problemas de optimización (función objetivo, variables de decisión, restricciones, espacio de búsqueda, óptimo local vs global, combinatoria vs continua); ascenso de colinas y sus problemas; recocido simulado; búsqueda tabú; algoritmos genéticos (codificación, aptitud, selección por ruleta o torneo, cruza, mutación, elitismo); programación lineal (región factible, vértices); colonias de hormigas y enjambre de partículas"},{"id":"t06","name":"Búsqueda con adversario y CSP","lvl":"SS","points":"minimax (valor de la raíz), poda alfa-beta (qué ramas se podan), función de evaluación; problemas de satisfacción de restricciones (variables, dominios, restricciones), backtracking, MRV, verificación hacia adelante, consistencia de arcos; coloreo de mapas"},{"id":"t07","name":"Representación del conocimiento","lvl":"S","points":"lógica proposicional y de predicados; reglas de producción; redes semánticas (es-un, parte-de, herencia); marcos (ranuras, facetas, valores por omisión); guiones; ontologías (RDF, OWL) y grafos de conocimiento; conocimiento declarativo vs procedimental; ventajas y limitaciones de cada técnica; identificar la representación usada en un ejemplo"},{"id":"t08","name":"Sistemas basados en conocimiento","lvl":"S","points":"arquitectura de un sistema experto: base de conocimiento, base de hechos (memoria de trabajo), motor de inferencia, módulo de explicación, módulo de adquisición e interfaz; ingeniero del conocimiento y experto del dominio; sistemas basados en reglas; MYCIN, DENDRAL; factores de certeza; ventajas y limitaciones"},{"id":"t09","name":"Encadenamiento hacia adelante y hacia atrás","lvl":"S","points":"razonamiento guiado por datos vs guiado por objetivos; traza del encadenamiento hacia adelante (reglas que se disparan, hechos nuevos); recorrido del encadenamiento hacia atrás (subobjetivos generados y su orden); resolución de conflictos (prioridad, especificidad, recencia); Prolog como encadenamiento hacia atrás"},{"id":"t10","name":"Lógica difusa","lvl":"S","points":"conjuntos difusos y grado de pertenencia; funciones de membresía triangular, trapezoidal y gaussiana (calcular μ(x)); operaciones mín, máx y complemento; variables lingüísticas y reglas SI-ENTONCES; inferencia Mamdani y Sugeno; fuzzificación, evaluación, agregación y defuzzificación (centroide)"},{"id":"t11","name":"Razonamiento con incertidumbre","lvl":"SS","points":"probabilidad condicional y teorema de Bayes (pruebas diagnósticas, filtros de spam); redes bayesianas (independencia condicional, probabilidad conjunta como producto de condicionales); clasificador Naive Bayes; cadenas de Markov a nivel conceptual"},{"id":"t12","name":"Redes neuronales","lvl":"SS","points":"neurona artificial (entradas, pesos, sesgo, suma ponderada, activación escalón, sigmoide, tanh, ReLU, softmax); perceptrón simple, regla de aprendizaje y separabilidad lineal (XOR); perceptrón multicapa: capas, número de pesos y sesgos, propagación hacia adelante, retropropagación y descenso por gradiente; tasa de aprendizaje, épocas, sobreajuste y regularización; CNN (convolución, pooling), RNN/LSTM y transformadores a nivel conceptual"},{"id":"t13","name":"Reconocimiento de patrones","lvl":"S","points":"tareas: clasificación, regresión, agrupamiento, detección y segmentación; etapas (adquisición, preprocesamiento, extracción de características, clasificación, evaluación); vector y espacio de características; procesamiento de imágenes (histograma, filtros de suavizado y realce, detección de bordes, umbralización, morfología); PLN básico (tokenización, lematización, bolsa de palabras, TF-IDF)"}]},{"code":"4.2","area":"A4","name":"Minería de datos","short":"Minería de datos","exam":10,"topics":[{"id":"t01","name":"KDD y metodologías","lvl":"S","points":"etapas del KDD (selección, preprocesamiento, transformación, minería, interpretación/evaluación) y su orden; CRISP-DM (comprensión del negocio, comprensión de los datos, preparación, modelado, evaluación, despliegue); SEMMA; tareas descriptivas vs predictivas (clasificación, regresión, agrupamiento, asociación, detección de anomalías)"},{"id":"t02","name":"Tipos de datos y estadística descriptiva","lvl":"S","points":"atributos nominales, ordinales, de intervalo y de razón; binarios simétricos y asimétricos; discretos vs continuos; estructurados, semiestructurados y no estructurados; series de tiempo, texto, datos espaciales y grafos; media, mediana, moda, varianza, desviación estándar, cuartiles, rango intercuartílico y valores atípicos (1.5·IQR)"},{"id":"t03","name":"Preprocesamiento de datos","lvl":"S","points":"limpieza: valores faltantes (eliminar, imputar media/mediana/moda), ruido (agrupamiento en intervalos, suavizado), atípicos; integración y redundancia; transformación: normalización min-max y z-score (cálculo), escalamiento decimal, discretización, codificación one-hot y ordinal; reducción por muestreo y agregación; desbalance de clases (sobremuestreo, SMOTE, submuestreo)"},{"id":"t04","name":"Selección y extracción de variables","lvl":"SS","points":"métodos de filtro (correlación, chi², ganancia de información, varianza), envoltura (selección hacia adelante/atrás, RFE) y embebidos (Lasso, importancia en árboles): ventajas y desventajas (costo, riesgo de sobreajuste, independencia del modelo); maldición de la dimensionalidad; PCA (componentes, varianza explicada); selección vs extracción"},{"id":"t05","name":"Similitud y distancia","lvl":"S","points":"distancia euclidiana (cálculo), Manhattan, Minkowski, Chebyshev; similitud coseno; Jaccard y coincidencia simple para binarios; Hamming; matriz de distancias o de semejanza (construir e interpretar); efecto de la escala y necesidad de normalizar"},{"id":"t06","name":"Tipos de aprendizaje automático","lvl":"S","points":"supervisado (clasificación vs regresión), no supervisado (agrupamiento, reducción de dimensionalidad, asociación), semisupervisado y por refuerzo (agente, recompensa, política); identificar el tipo de aprendizaje en un escenario; sesgo-varianza, sobreajuste y subajuste"},{"id":"t07","name":"Clasificación","lvl":"SS","points":"k vecinos más cercanos (calcular la clase con k dado, empates, elección de k, normalización); árboles de decisión (entropía, ganancia de información e índice Gini con cálculo, ID3, C4.5, CART, poda); Naive Bayes; regresión logística; SVM (margen, vectores de soporte, kernel); ensambles: bagging, random forest y boosting"},{"id":"t08","name":"Evaluación de modelos","lvl":"S","points":"matriz de confusión (VP, VN, FP, FN) y cálculo de exactitud, precisión, exhaustividad (recall), especificidad y F1; curva ROC y AUC; entrenamiento, validación y prueba; validación cruzada k-fold y dejar uno fuera; métricas de regresión (MAE, MSE, RMSE, R²); comparar una matriz de confusión (aprendizaje) con una matriz de semejanza"},{"id":"t09","name":"Agrupamiento","lvl":"SS","points":"k-means (asignación y recálculo de centroides en una iteración, elección de k, método del codo, sensibilidad a la inicialización), k-medoides; agrupamiento jerárquico aglomerativo y divisivo con enlace simple, completo, promedio y Ward; leer un dendrograma y obtener los grupos al cortarlo a cierta altura; DBSCAN (punto núcleo, borde y ruido); coeficiente de silueta"},{"id":"t10","name":"Reglas de asociación","lvl":"SS","points":"conjuntos de ítems, soporte, confianza y lift (cálculo e interpretación); algoritmo Apriori y propiedad antimonótona; generación de candidatos; FP-Growth a nivel conceptual; análisis de canasta de mercado"},{"id":"t11","name":"Regresión y correlación","lvl":"S","points":"regresión lineal simple por mínimos cuadrados (interpretar pendiente e intercepto, predecir); coeficiente de correlación de Pearson; correlación no implica causalidad; regresión múltiple; tendencia y estacionalidad en series de tiempo"},{"id":"t12","name":"Big data y herramientas","lvl":"S","points":"las V del big data (volumen, velocidad, variedad, veracidad, valor); Hadoop (HDFS, MapReduce: fases map, shuffle y reduce, conteo de palabras); Spark (procesamiento en memoria); herramientas (Weka, RapidMiner, scikit-learn, R); minería de texto y web; privacidad, anonimización y sesgo"}]},{"code":"4.3","area":"A4","name":"Cómputo distribuido","short":"Cómputo distribuido","exam":10,"topics":[{"id":"t01","name":"Fundamentos de sistemas distribuidos","lvl":"S","points":"definición; objetivos: compartir recursos, transparencias (acceso, ubicación, migración, reubicación, replicación, concurrencia, fallas), apertura y escalabilidad (tamaño, geográfica, administrativa); desafíos (heterogeneidad, fallas parciales, seguridad, concurrencia); falacias de la computación distribuida; clusters, grids, nubes, IoT"},{"id":"t02","name":"Arquitecturas distribuidas","lvl":"S","points":"cliente-servidor de 2, 3 y n capas; peer-to-peer estructurado (DHT, Chord) y no estructurado; híbridas; middleware; SOA y microservicios; publicar-suscribir y basadas en eventos; cluster vs grid vs nube"},{"id":"t03","name":"Procesos e hilos","lvl":"S","points":"proceso vs hilo (qué comparten y qué es propio de cada hilo); ventajas del multihilo; modelos muchos-a-uno, uno-a-uno, muchos-a-muchos; hilos en Java (Thread, Runnable, start vs run, join, synchronized, volatile, ExecutorService) y salidas posibles; pthreads; servidores multihilo; condición de carrera con un contador compartido; ejecución secuencial vs paralela"},{"id":"t04","name":"Programación paralela","lvl":"SS","points":"paralelismo de datos vs de tareas; granularidad y balanceo de carga; aceleración S = T₁/Tₚ y eficiencia E = S/p; ley de Amdahl y de Gustafson (cálculo); memoria compartida (OpenMP: parallel for, reduction) vs paso de mensajes (MPI: rank, size, send/recv, broadcast, scatter/gather, reduce); GPU y CUDA a nivel conceptual"},{"id":"t05","name":"Modos de comunicación","lvl":"SS","points":"comunicación síncrona/asíncrona, persistente/transitoria, bloqueante/no bloqueante; sockets TCP y UDP; RPC (stubs, marshalling, semánticas al menos una vez, a lo más una vez, exactamente una vez); RMI; middleware orientado a mensajes (colas, RabbitMQ, Kafka); publicar-suscribir; multidifusión y comunicación en grupo; REST, SOAP, gRPC; serialización (JSON, XML, Protocol Buffers); qué modo conviene según la arquitectura"},{"id":"t06","name":"Sincronización y coordinación","lvl":"SS","points":"relojes físicos (Cristian, Berkeley, NTP); relojes lógicos de Lamport (calcular marcas) y relojes vectoriales (relación sucedió-antes y concurrencia); exclusión mutua distribuida (centralizada, Ricart-Agrawala, anillo con testigo); algoritmos de elección (abusón, anillo); consenso (Paxos, Raft) y generales bizantinos"},{"id":"t07","name":"Replicación y consistencia","lvl":"SS","points":"motivos para replicar; modelos de consistencia estricta, secuencial, causal y eventual; réplica primaria vs replicación activa; quórums (R + W > N, cálculo); teorema CAP y ejemplos CP/AP; ACID vs BASE"},{"id":"t08","name":"Tolerancia a fallas","lvl":"S","points":"tipos de falla (caída, omisión, temporización, respuesta, bizantina) y fail-stop; confiabilidad vs disponibilidad (MTBF, MTTR, A = MTBF/(MTBF+MTTR), nueves); redundancia de información, de tiempo y física; TMR y votación; replicación de procesos (k+1 o 2k+1 réplicas, 3k+1 para fallas bizantinas); detección por latidos (heartbeat); puntos de control y recuperación hacia atrás/adelante; commit atómico distribuido (2PC, 3PC); failover"},{"id":"t09","name":"Cómputo en la nube","lvl":"S","points":"características esenciales del NIST (autoservicio bajo demanda, acceso amplio por red, agrupación de recursos, elasticidad rápida, servicio medido); IaaS, PaaS, SaaS y FaaS/serverless con ejemplos; nube pública, privada, híbrida y comunitaria; virtualización (hipervisor tipo 1 y 2), máquinas virtuales vs contenedores (Docker) y Kubernetes; escalamiento vertical vs horizontal; balanceo de carga; responsabilidad compartida; SLA y multitenencia"},{"id":"t10","name":"Grid computing y otros paradigmas","lvl":"SS","points":"arquitectura en capas del grid (fábrica, conectividad, recursos, colectiva, aplicación); organizaciones virtuales y middleware (Globus Toolkit); grid vs cluster vs nube (propiedad, heterogeneidad, acoplamiento, administración); computación voluntaria (BOINC); edge y fog computing; sistemas de archivos distribuidos (NFS, HDFS, GFS)"}]},{"code":"LC1","area":"LC","name":"Comprensión lectora","short":"Comprensión lectora","exam":30,"topics":[{"id":"t01","name":"Ámbito de estudio","lvl":"S","points":"reseña académica y artículo de investigación (originales, de divulgación tecnológica o social); cada texto con 3 preguntas: identificación de información, interpretación (idea central, sentido de una frase) y evaluación de la forma y el contenido (ejemplo que ilustra, por qué se incluye un elemento, intención del autor)"},{"id":"t02","name":"Ámbito literario","lvl":"S","points":"cuento y ensayo literario (originales); 3 preguntas por texto: identificación, interpretación y evaluación"},{"id":"t03","name":"Ámbito de participación social","lvl":"S","points":"convocatoria y nota informativa (originales, con datos concretos: fechas, requisitos, montos); 3 preguntas por texto: identificación, interpretación y evaluación"}]},{"code":"LC2","area":"LC","name":"Redacción indirecta","short":"Redacción indirecta","exam":30,"topics":[{"id":"t01","name":"Dimensión comunicativa","lvl":"S","points":"elegir el fragmento con el registro (formal, informal, especializado) y las características de género adecuados: artículo de divulgación científica, protocolo de investigación, reseña, editorial de periódico, convocatoria, carta de exposición de motivos; ámbitos de estudio y de participación social"},{"id":"t02","name":"Dimensión gramatical y semántica","lvl":"SS","points":"elegir el enunciado correctamente redactado: concordancia nominal (género y número, sustantivos de distinto género → masculino plural) y verbal (sujeto compuesto, colectivos); cohesión gramatical (referencia/pronombres, elipsis, sustitución), léxico-semántica (sinónimos, hiperónimos, repetición) y textual (conectores y marcadores discursivos adecuados); orden lógico de oraciones"},{"id":"t03","name":"Dimensión ortográfica","lvl":"S","points":"elegir el enunciado con ortografía correcta según la RAE (2010): grafías b/v, c/s/z, g/j, h, ll/y, x; acentuación de agudas, graves y esdrújulas, hiatos, tilde diacrítica (tú/tu, él/el, mí/mi, sé/se, más/mas, té/te, sí/si, dé/de), interrogativos y exclamativos (qué, cómo, dónde, por qué/porque/porqué/por que), solo y demostrativos sin tilde, monosílabos como guion, fue, dio, vio; puntuación (coma vocativa, explicativa y enumerativa; punto y coma; dos puntos; comillas); mayúsculas con tilde"}]}],"files":["q-1.1.js","q-1.2.js","q-1.4.js","q-2.2.js","q-2.3.js","q-3.1.js","q-3.2.js","q-4.1.js","q-4.2.js","q-4.3.js"],"notes":{"1.1":"n-1.1.js","1.2":"n-1.2.js","1.3":"n-1.3.js","1.4":"n-1.4.js","2.1":"n-2.1.js","2.2":"n-2.2.js","2.3":"n-2.3.js","3.1":"n-3.1.js","3.2":"n-3.2.js","3.3":"n-3.3.js","3.4":"n-3.4.js","4.1":"n-4.1.js","4.2":"n-4.2.js","4.3":"n-4.3.js","LC1":"n-LC1.js"},"counts":{"1.1":108,"1.2":123,"1.3":0,"1.4":66,"2.1":0,"2.2":38,"2.3":102,"3.1":33,"3.2":62,"3.3":0,"3.4":0,"4.1":104,"4.2":130,"4.3":112,"LC1":0,"LC2":0},"total":878});
